127	/// \brief Base class for all data types
128	///
129	/// Data types in this library are all *logical*. They can be expressed as
130	/// either a primitive physical type (bytes or bits of some fixed size), a
131	/// nested type consisting of other data types, or another data type (e.g. a
132	/// timestamp encoded as an int64).
133	///
134	/// Simple datatypes may be entirely described by their Type::type id, but
135	/// complex datatypes are usually parametric.
136	class ARROW_EXPORT DataType : public std::enable_shared_from_this<DataType>,
137	                              public detail::Fingerprintable,
138	                              public util::EqualityComparable<DataType> {
139	 public:
140	  explicit DataType(Type::type id) : detail::Fingerprintable(), id_(id) {}
141	  ~DataType() override;
142	
143	  /// \brief Return whether the types are equal
144	  ///
145	  /// Types that are logically convertible from one to another (e.g. List<UInt8>
146	  /// and Binary) are NOT equal.
147	  bool Equals(const DataType& other, bool check_metadata = false) const;
148	
149	  /// \brief Return whether the types are equal
150	  bool Equals(const std::shared_ptr<DataType>& other, bool check_metadata = false) const;
151	
152	  /// \brief Return the child field at index i.
153	  const std::shared_ptr<Field>& field(int i) const { return children_[i]; }
154	
155	  /// \brief Return the children fields associated with this type.
156	  const FieldVector& fields() const { return children_; }
157	
158	  /// \brief Return the number of children fields associated with this type.
159	  int num_fields() const { return static_cast<int>(children_.size()); }
160	
161	  /// \brief Apply the TypeVisitor::Visit() method specialized to the data type
162	  Status Accept(TypeVisitor* visitor) const;
163	
164	  /// \brief A string representation of the type, including any children
165	  virtual std::string ToString(bool show_metadata = false) const = 0;
166	
167	  /// \brief Return hash value (excluding metadata in child fields)
168	  size_t Hash() const;
169	
170	  /// \brief A string name of the type, omitting any child fields
171	  ///
172	  /// \since 0.7.0
173	  virtual std::string name() const = 0;
174	
175	  /// \brief Return the data type layout.  Children are not included.
176	  ///
177	  /// \note Experimental API
178	  virtual DataTypeLayout layout() const = 0;
179	
180	  /// \brief Return the type category
181	  Type::type id() const { return id_; }
182	
183	  /// \brief Return the type category of the storage type
184	  virtual Type::type storage_id() const { return id_; }
185	
186	  /// \brief Returns the type's fixed byte width, if any. Returns -1
187	  /// for non-fixed-width types, and should only be used for
188	  /// subclasses of FixedWidthType
189	  virtual int32_t byte_width() const {
190	    int32_t num_bits = this->bit_width();
191	    return num_bits > 0 ? num_bits / 8 : -1;
192	  }
193	
194	  /// \brief Returns the type's fixed bit width, if any. Returns -1
195	  /// for non-fixed-width types, and should only be used for
196	  /// subclasses of FixedWidthType
197	  virtual int bit_width() const { return -1; }
198	
199	  // \brief EXPERIMENTAL: Enable retrieving shared_ptr<DataType> from a const
200	  // context.
201	  std::shared_ptr<DataType> GetSharedPtr() const {
202	    return const_cast<DataType*>(this)->shared_from_this();
203	  }
204	
205	 protected:
