207	  // Subclasses should override for fast equality checks.
208	  std::string ComputeFingerprint() const override;
209	
210	  // Generic versions that works for all regular types, nested or not.
211	  std::string ComputeMetadataFingerprint() const override;
212	
213	  Type::type id_;
214	  FieldVector children_;
215	
216	 private:
217	  ARROW_DISALLOW_COPY_AND_ASSIGN(DataType);
218	};
